@Service @Transactional
public class LdParticipationServiceImpl implements LdParticipationService {
    private static final String REQUEST_CODE="LEARNING_NOMINATION";
    private static final List<LdEnrollment.Status> ACTIVE_ENROLLMENTS=List.of(LdEnrollment.Status.INVITED,LdEnrollment.Status.CONFIRMED);
    private final LdNominationRepository nominations; private final LdNominationRouteRepository routes;
    private final LdNominationRouteStepRepository steps; private final LdEnrollmentRepository enrollments;
    private final LdTrainingOrderSourceRepository orders; private final LdTrainingOrderParticipantRepository orderParticipants;
    private final LdOfferingRepository offerings; private final LdOfferingSessionRepository sessions;
    private final LdProgramRepository programs; private final LdProgramSourceRepository programSources;
    private final LdConsolidatedPlanSourceRepository planSources;
    private final LdIndividualDevelopmentPlanRepository idps; private final LdIndividualDevelopmentPlanItemRepository idpItems;
    private final HumanResourceAssessmentSubjectClient hr; private final HumanResourcePerformanceParticipantClient participants; private final AdministrativePerformancePlanningClient admin;
    private final PrimeHrAuditService audit;

    public LdParticipationServiceImpl(LdNominationRepository nominations,LdNominationRouteRepository routes,
            LdNominationRouteStepRepository steps,LdEnrollmentRepository enrollments,
            LdTrainingOrderSourceRepository orders,LdTrainingOrderParticipantRepository orderParticipants,
            LdOfferingRepository offerings,LdOfferingSessionRepository sessions,LdProgramRepository programs,
            LdProgramSourceRepository programSources,LdConsolidatedPlanSourceRepository planSources,
            LdIndividualDevelopmentPlanRepository idps,LdIndividualDevelopmentPlanItemRepository idpItems,
            HumanResourceAssessmentSubjectClient hr,HumanResourcePerformanceParticipantClient participants,AdministrativePerformancePlanningClient admin,PrimeHrAuditService audit){
        this.nominations=nominations;this.routes=routes;this.steps=steps;this.enrollments=enrollments;this.orders=orders;
        this.orderParticipants=orderParticipants;this.offerings=offerings;this.sessions=sessions;this.programs=programs;
        this.programSources=programSources;this.planSources=planSources;this.idps=idps;this.idpItems=idpItems;
        this.hr=hr;this.participants=participants;this.admin=admin;this.audit=audit;
    }

    @Override @Transactional(readOnly=true) public List<NominationResponse> nominations(String agency,String actor,PermissionDataScope scope){
        return nominations.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(n->visible(agency,n,actor,scope)).map(n->response(agency,n)).toList();
    }
    @Override @Transactional(readOnly=true) public NominationResponse nomination(String agency,String id,String actor,PermissionDataScope scope){LdNomination n=nomination(agency,id);access(agency,n,actor,scope);return response(agency,n);}
    @Override public NominationResponse create(String agency,NominationCreate in,String token,String actor,PermissionDataScope scope,String correlation){
        LdOffering offering=offering(agency,in.offeringId());published(offering);mutableEnrollment(agency,offering.getId());List<LdOfferingSession> schedule=schedule(agency,offering.getId());
        HumanResourceAssessmentSubject employee=hr.get(in.employeeId(),token);var membership=admin.membership(employee.employeeId(),token);
        createAccess(employee.employeeNo(),membership.businessUnitId(),actor,scope,token);
        if(nominations.existsByAgencyIdAndOfferingIdAndEmployeeId(agency,offering.getId(),employee.employeeId()))throw new OptimisticConflictException("Employee already has a nomination for this offering");
        ensureNoOverlap(agency,employee.employeeNo(),schedule.get(0).getStartsAt(),schedule.get(schedule.size()-1).getEndsAt(),null);
        Source source=source(agency,offering,in,employee);
        LdNomination.InitiatorType initiator=actor.equalsIgnoreCase(employee.employeeNo())?LdNomination.InitiatorType.EMPLOYEE:(scope==PermissionDataScope.AGENCY_WIDE?LdNomination.InitiatorType.LD_STAFF:LdNomination.InitiatorType.SUPERVISOR);
        LdNomination n=nominations.saveAndFlush(new LdNomination(agency,offering.getId(),offering.getOfferingVersion(),offeringFingerprint(offering),offering.getTitle(),schedule.get(0).getStartsAt(),schedule.get(schedule.size()-1).getEndsAt(),in.sourceType(),source.id(),source.version(),source.fingerprint(),in.justification(),employee.employeeId(),employee.employeeNo(),employee.displayName(),employee.appointmentId(),employee.sourceFingerprint(),membership.businessUnitId(),membership.businessUnitName(),membership.areaId(),membership.areaName(),membership.sourceFingerprint(),in.estimatedCost(),initiator,actor));
        NominationResponse out=response(agency,n);record(agency,"CREATE_LD_NOMINATION","LD_NOMINATION",n.getId(),n.getContentRevision(),n.getVersion(),null,out,null,correlation);return out;
    }
    @Override public NominationResponse update(String agency,String id,NominationUpdate in,String actor,PermissionDataScope scope,String correlation){LdNomination n=nomination(agency,id);access(agency,n,actor,scope);check(n.getVersion(),in.recordVersion());var before=response(agency,n);n.update(in.justification(),in.estimatedCost());n=nominations.saveAndFlush(n);return changed(agency,n,"UPDATE_LD_NOMINATION",before,null,correlation);}
    @Override public NominationResponse submit(String agency,String id,Transition in,String token,String actor,PermissionDataScope scope,String correlation){
        LdNomination n=nomination(agency,id);access(agency,n,actor,scope);check(n.getVersion(),in.recordVersion());mutableEnrollment(agency,n.getOfferingId());validateSnapshots(n,token);LdOffering o=offering(agency,n.getOfferingId());published(o);ensureNoOverlap(agency,n.getEmployeeNo(),n.getScheduleStart(),n.getScheduleEnd(),null);
        var configured=admin.approvalRoute(n.getBusinessUnitId(),REQUEST_CODE,token);validateRoute(configured,n);
        var previous=response(agency,n);int revision=routes.findFirstByAgencyIdAndNominationIdOrderByRouteRevisionDesc(agency,id).map(r->r.getRouteRevision()+1).orElse(1);
        routes.findFirstByAgencyIdAndNominationIdOrderByRouteRevisionDesc(agency,id).filter(r->r.getStatus()==LdNominationRoute.Status.ACTIVE).ifPresent(r->r.finish(LdNominationRoute.Status.SUPERSEDED));
        LdNominationRoute route=routes.saveAndFlush(new LdNominationRoute(agency,id,revision,REQUEST_CODE,n.getBusinessUnitId(),configured.sourceFingerprint(),n.getContentRevision(),actor,Instant.now()));
        int last=configured.steps().size();for(var configuredStep:configured.steps()){HumanResourceAssessmentSubject participant=hr.get(configuredStep.employeeId(),token);var membership=admin.membership(participant.employeeId(),token);if(!Objects.equals(membership.businessUnitId(),n.getBusinessUnitId()))throw new IllegalArgumentException("Every nomination route actor must belong to the nominee Business Unit");steps.save(new LdNominationRouteStep(agency,route.getId(),configuredStep.level(),configuredStep.level()==last?LdNominationRouteStep.Action.APPROVE:LdNominationRouteStep.Action.RECOMMEND,participant.employeeId(),participant.employeeNo(),participant.displayName(),participant.appointmentId(),participant.sourceFingerprint(),membership.sourceFingerprint()));}steps.flush();
        n.submit(actor,Instant.now());n=nominations.saveAndFlush(n);return changed(agency,n,"SUBMIT_LD_NOMINATION",previous,in.reason(),correlation);
    }
    @Override public NominationResponse recommend(String agency,String id,Transition in,String token,String actor,String correlation){return decide(agency,id,in,token,actor,false,false,correlation);}
    @Override public NominationResponse returnForChanges(String agency,String id,Transition in,String token,String actor,String correlation){return decide(agency,id,in,token,actor,true,false,correlation);}
    @Override public NominationResponse approve(String agency,String id,Transition in,String token,String actor,String correlation){return decide(agency,id,in,token,actor,false,true,correlation);}
    private NominationResponse decide(String agency,String id,Transition in,String token,String actor,boolean returned,boolean approved,String correlation){
        LdNomination n=nomination(agency,id);check(n.getVersion(),in.recordVersion());LdNominationRoute route=activeRoute(agency,id);LdNominationRouteStep step=steps.findByAgencyIdAndRouteIdAndLevel(agency,route.getId(),route.getCurrentLevel()).orElseThrow(()->new IllegalStateException("Current nomination route step is missing"));
        if(!actor.equalsIgnoreCase(step.getEmployeeNo()))throw new AccessDeniedException("Only the current nomination approver may act");validateActor(step,token);
        var before=response(agency,n);Instant now=Instant.now();
        if(returned){step.decide(LdNominationRouteStep.Status.RETURNED,actor,requiredReason(in.reason()),now);steps.findByAgencyIdAndRouteIdOrderByLevelAsc(agency,route.getId()).forEach(LdNominationRouteStep::skip);route.finish(LdNominationRoute.Status.RETURNED);n.returnForChanges(in.reason());}
        else if(approved){if(step.getAction()!=LdNominationRouteStep.Action.APPROVE)throw new IllegalStateException("Current route step is a recommendation step");mutableEnrollment(agency,n.getOfferingId());validateSnapshots(n,token);published(offering(agency,n.getOfferingId()));ensureCapacity(agency,n.getOfferingId());ensureNoOverlap(agency,n.getEmployeeNo(),n.getScheduleStart(),n.getScheduleEnd(),null);step.decide(LdNominationRouteStep.Status.APPROVED,actor,in.reason(),now);route.finish(LdNominationRoute.Status.COMPLETED);n.approve(actor,now);n=nominations.saveAndFlush(n);enrollments.saveAndFlush(new LdEnrollment(agency,n.getId(),n.getOfferingId(),n.getOfferingVersion(),n.getOfferingFingerprint(),n.getEmployeeId(),n.getEmployeeNo(),n.getEmployeeName(),n.getAppointmentId(),n.getEmployeeFingerprint()));}
        else {if(step.getAction()!=LdNominationRouteStep.Action.RECOMMEND)throw new IllegalStateException("Final route step requires approval");step.decide(LdNominationRouteStep.Status.RECOMMENDED,actor,in.reason(),now);n.recommend();int next=route.getCurrentLevel()+1;LdNominationRouteStep nextStep=steps.findByAgencyIdAndRouteIdAndLevel(agency,route.getId(),next).orElseThrow(()->new IllegalStateException("Next nomination route step is missing"));nextStep.makeCurrent();route.advance(next);}
        steps.flush();routes.saveAndFlush(route);n=nominations.saveAndFlush(n);return changed(agency,n,returned?"RETURN_LD_NOMINATION":approved?"APPROVE_LD_NOMINATION":"RECOMMEND_LD_NOMINATION",before,in.reason(),correlation);
    }
    @Override public NominationResponse cancel(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdNomination n=nomination(agency,id);access(agency,n,actor,scope);check(n.getVersion(),in.recordVersion());var before=response(agency,n);n.cancel();routes.findFirstByAgencyIdAndNominationIdOrderByRouteRevisionDesc(agency,id).filter(r->r.getStatus()==LdNominationRoute.Status.ACTIVE).ifPresent(r->r.finish(LdNominationRoute.Status.CANCELLED));n=nominations.saveAndFlush(n);return changed(agency,n,"CANCEL_LD_NOMINATION",before,in.reason(),correlation);}

    @Override @Transactional(readOnly=true) public List<EnrollmentResponse> enrollments(String agency,String actor,PermissionDataScope scope){return enrollments.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(e->enrollmentVisible(agency,e,actor,scope)).map(this::enrollmentResponse).toList();}
    @Override @Transactional(readOnly=true) public EnrollmentResponse enrollment(String agency,String id,String actor,PermissionDataScope scope){LdEnrollment e=enrollment(agency,id);enrollmentAccess(agency,e,actor,scope);return enrollmentResponse(e);}
    @Override public EnrollmentResponse confirm(String agency,String id,Transition in,String token,String actor,String correlation){LdEnrollment e=enrollment(agency,id);own(e,actor);check(e.getVersion(),in.recordVersion());mutableEnrollment(agency,e.getOfferingId());validateEnrollmentSnapshot(e,token);published(offering(agency,e.getOfferingId()));var before=enrollmentResponse(e);e.confirm(Instant.now());e=enrollments.saveAndFlush(e);return enrollmentChanged(agency,e,"CONFIRM_LD_ENROLLMENT",before,in.reason(),correlation);}
    @Override public EnrollmentResponse decline(String agency,String id,Transition in,String actor,String correlation){LdEnrollment e=enrollment(agency,id);own(e,actor);check(e.getVersion(),in.recordVersion());mutableEnrollment(agency,e.getOfferingId());var before=enrollmentResponse(e);e.decline(requiredReason(in.reason()),Instant.now());e=enrollments.saveAndFlush(e);return enrollmentChanged(agency,e,"DECLINE_LD_ENROLLMENT",before,in.reason(),correlation);}
    @Override public EnrollmentResponse cancelEnrollment(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdEnrollment e=enrollment(agency,id);enrollmentAccess(agency,e,actor,scope);check(e.getVersion(),in.recordVersion());mutableEnrollment(agency,e.getOfferingId());var before=enrollmentResponse(e);e.cancel(requiredReason(in.reason()),Instant.now());e=enrollments.saveAndFlush(e);return enrollmentChanged(agency,e,"CANCEL_LD_ENROLLMENT",before,in.reason(),correlation);}
    @Override public EnrollmentResponse substitute(String agency,String id,SubstitutionInput in,String actor,PermissionDataScope scope,String correlation){if(scope==PermissionDataScope.OWN_RECORDS)throw new AccessDeniedException("Substitution requires assigned or agency scope");LdEnrollment old=enrollment(agency,id),replacement=enrollment(agency,in.replacementEnrollmentId());enrollmentAccess(agency,old,actor,scope);enrollmentAccess(agency,replacement,actor,scope);check(old.getVersion(),in.recordVersion());check(replacement.getVersion(),in.replacementRecordVersion());if(!old.getOfferingId().equals(replacement.getOfferingId()))throw new IllegalArgumentException("Replacement enrollment must belong to the same offering");mutableEnrollment(agency,old.getOfferingId());if(old.getEmployeeId().equals(replacement.getEmployeeId()))throw new IllegalArgumentException("Replacement employee must differ from the original participant");var before=enrollmentResponse(old);old.substituteWith(replacement,in.reason(),Instant.now());enrollments.save(replacement);old=enrollments.saveAndFlush(old);return enrollmentChanged(agency,old,"SUBSTITUTE_LD_ENROLLMENT",before,in.reason(),correlation);}

    @Override @Transactional(readOnly=true) public TrainingOrderResponse trainingOrder(String agency,String offeringId,String actor,PermissionDataScope scope){LdOffering offering=offering(agency,offeringId);LdProgram program=programs.findByIdAndAgencyId(offering.getProgramId(),agency).orElseThrow(()->new ResourceNotFoundException("L&D program not found"));if(scope!=PermissionDataScope.AGENCY_WIDE&&!program.getAccountableEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Training Order is outside the permitted data scope");return orderResponse(agency,orders.findByAgencyIdAndOfferingId(agency,offeringId).orElseThrow(()->new ResourceNotFoundException("Training Order source not found")));}
    @Override public TrainingOrderResponse finalizeTrainingOrder(String agency,String offeringId,TrainingOrderInput in,String actor,PermissionDataScope scope,String correlation){
        if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Training Order finalization requires Agency Wide scope");LdOffering offering=offering(agency,offeringId);published(offering);schedule(agency,offeringId);
        if(orders.findByAgencyIdAndOfferingId(agency,offeringId).isPresent())throw new OptimisticConflictException("Training Order source is already finalized for this offering");String normalized=in.orderNumber().trim().toUpperCase(Locale.ROOT);if(orders.existsByAgencyIdAndNormalizedOrderNumber(agency,normalized))throw new OptimisticConflictException("Training Order number already exists");
        if(nominations.existsByAgencyIdAndOfferingIdAndStatusIn(agency,offeringId,List.of(LdNomination.Status.SUBMITTED,LdNomination.Status.RECOMMENDED)))throw new OptimisticConflictException("Training Order cannot be finalized while nominations are awaiting approval");List<LdEnrollment> roster=enrollments.findByAgencyIdAndOfferingIdOrderByCreatedAtAsc(agency,offeringId);if(roster.stream().anyMatch(e->e.getStatus()==LdEnrollment.Status.INVITED))throw new OptimisticConflictException("Training Order cannot be finalized while participant confirmations are pending");List<LdEnrollment> active=roster.stream().filter(e->e.getStatus()==LdEnrollment.Status.CONFIRMED).toList();if(active.isEmpty())throw new IllegalStateException("Training Order requires at least one confirmed participant");
        String fingerprint=hash(offeringFingerprint(offering)+"|"+normalized+"|"+in.subject()+"|"+in.attendanceDirective()+"|"+active.stream().map(this::enrollmentFingerprint).sorted().toList());
        LdTrainingOrderSource order=orders.saveAndFlush(new LdTrainingOrderSource(agency,offeringId,offering.getOfferingVersion(),offeringFingerprint(offering),in.orderNumber(),in.subject(),in.attendanceDirective(),in.dressCode(),in.notes(),actor,Instant.now(),fingerprint));int display=1;for(LdEnrollment e:active)orderParticipants.save(new LdTrainingOrderParticipant(agency,order.getId(),e,enrollmentFingerprint(e),display++));orderParticipants.flush();TrainingOrderResponse out=orderResponse(agency,order);record(agency,"FINALIZE_LD_TRAINING_ORDER_SOURCE","LD_TRAINING_ORDER",order.getId(),offering.getOfferingVersion(),order.getVersion(),null,out,null,correlation);return out;
    }

    private Source source(String agency,LdOffering offering,NominationCreate in,HumanResourceAssessmentSubject employee){
        if(in.sourceType()==LdNomination.SourceType.IDP_ITEM){LdIndividualDevelopmentPlanItem item=idpItems.findByIdAndAgencyId(in.sourceId(),agency).orElseThrow(()->new ResourceNotFoundException("Approved IDP item not found"));LdIndividualDevelopmentPlan plan=idps.findByIdAndAgencyId(item.getPlanId(),agency).orElseThrow(()->new ResourceNotFoundException("IDP not found"));if(plan.getStatus()!=LdIndividualDevelopmentPlan.Status.APPROVED||!plan.getEmployeeId().equals(employee.employeeId()))throw new IllegalArgumentException("IDP source must be approved and belong to the nominee");return new Source(item.getId(),item.getVersion(),hash(item.getId()+"|"+item.getDevelopmentObjective()+"|"+item.getSuccessMeasure()+"|"+item.getTargetDate()));}
        if(in.sourceType()==LdNomination.SourceType.PLAN_SOURCE){LdProgramSource ps=programSources.findByIdAndAgencyIdAndProgramId(in.sourceId(),agency,offering.getProgramId()).orElseThrow(()->new ResourceNotFoundException("Offering program source not found"));LdConsolidatedPlanSource source=planSources.findByIdAndAgencyId(ps.getPlanSourceId(),agency).orElseThrow(()->new ResourceNotFoundException("Approved plan source not found"));if(source.getEmployeeNo()!=null&&!source.getEmployeeNo().equalsIgnoreCase(employee.employeeNo()))throw new IllegalArgumentException("Employee-specific plan source belongs to another employee");return new Source(ps.getId(),ps.getVersion(),ps.getSourceFingerprint());}
        if(in.sourceType()!=LdNomination.SourceType.JUSTIFIED)throw new IllegalArgumentException("Unsupported nomination source type");if(in.sourceId()!=null&&!in.sourceId().isBlank())throw new IllegalArgumentException("Justified nomination cannot specify sourceId");return new Source(null,null,null);
    }
    private void validateRoute(AdministrativePerformancePlanningClient.ApprovalRoute route,LdNomination n){if(route==null||!REQUEST_CODE.equals(route.requestCode())||!Objects.equals(route.businessUnitId(),n.getBusinessUnitId())||route.steps()==null||route.steps().isEmpty()||route.steps().size()!=route.configuredMaximum())throw new IllegalArgumentException("Configured L&D nomination approval route is invalid");Set<Long> actors=new HashSet<>();for(int i=0;i<route.steps().size();i++){var s=route.steps().get(i);if(s.level()!=i+1||!actors.add(s.employeeId()))throw new IllegalArgumentException("Approval route levels must be contiguous and actors unique");}if(route.steps().get(route.steps().size()-1).employeeId().equals(n.getEmployeeId()))throw new IllegalArgumentException("Nominee cannot finally approve their own nomination");}
    private void validateActor(LdNominationRouteStep step,String token){HumanResourceAssessmentSubject current=hr.get(step.getEmployeeId(),token);var membership=admin.membership(current.employeeId(),token);if(!Objects.equals(current.appointmentId(),step.getAppointmentId())||!Objects.equals(current.sourceFingerprint(),step.getParticipantFingerprint())||!Objects.equals(membership.sourceFingerprint(),step.getOrganizationFingerprint()))throw new OptimisticConflictException("Approval actor appointment or organization assignment changed; resubmit the nomination");}
    private void validateSnapshots(LdNomination n,String token){HumanResourceAssessmentSubject current=hr.get(n.getEmployeeId(),token);var membership=admin.membership(current.employeeId(),token);if(!Objects.equals(current.appointmentId(),n.getAppointmentId())||!Objects.equals(current.sourceFingerprint(),n.getEmployeeFingerprint())||!Objects.equals(membership.businessUnitId(),n.getBusinessUnitId())||!Objects.equals(membership.sourceFingerprint(),n.getOrganizationFingerprint()))throw new OptimisticConflictException("Nominee appointment or organization assignment changed; revise the nomination");}
    private void validateEnrollmentSnapshot(LdEnrollment e,String token){HumanResourceAssessmentSubject current=hr.get(e.getEmployeeId(),token);if(!Objects.equals(current.appointmentId(),e.getAppointmentId())||!Objects.equals(current.sourceFingerprint(),e.getEmployeeFingerprint()))throw new OptimisticConflictException("Participant appointment changed; enrollment must be reviewed");}
    private void ensureCapacity(String agency,String offering){LdOffering o=offering(agency,offering);if(enrollments.countByAgencyIdAndOfferingIdAndStatusIn(agency,offering,ACTIVE_ENROLLMENTS)>=o.getCapacity())throw new OptimisticConflictException("Offering capacity has been reached");}
    private void ensureNoOverlap(String agency,String employee,OffsetDateTime start,OffsetDateTime end,String excluded){for(LdEnrollment e:enrollments.findByAgencyIdAndEmployeeNoAndStatusIn(agency,employee,ACTIVE_ENROLLMENTS)){if(excluded!=null&&excluded.equals(e.getId()))continue;LdNomination n=nomination(agency,e.getNominationId());if(start.isBefore(n.getScheduleEnd())&&end.isAfter(n.getScheduleStart()))throw new OptimisticConflictException("Employee has an overlapping active L&D enrollment");}}
    private List<LdOfferingSession> schedule(String agency,String offering){List<LdOfferingSession> rows=sessions.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,offering);if(rows.isEmpty())throw new IllegalStateException("Published offering requires at least one session");return rows.stream().sorted(Comparator.comparing(LdOfferingSession::getStartsAt)).toList();}
    private void published(LdOffering o){if(o.getStatus()!=LdOffering.Status.PUBLISHED)throw new IllegalStateException("Only a PUBLISHED offering accepts nominations or Training Orders");}
    private boolean visible(String agency,LdNomination n,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return true;if(n.getEmployeeNo().equalsIgnoreCase(actor)||n.getInitiatedBy().equalsIgnoreCase(actor))return true;if(scope==PermissionDataScope.ASSIGNED_RECORDS)return routes.findFirstByAgencyIdAndNominationIdOrderByRouteRevisionDesc(agency,n.getId()).map(r->steps.findByAgencyIdAndRouteIdOrderByLevelAsc(agency,r.getId()).stream().anyMatch(s->s.getEmployeeNo().equalsIgnoreCase(actor))).orElse(false);return false;}
    private void access(String agency,LdNomination n,String actor,PermissionDataScope scope){if(!visible(agency,n,actor,scope))throw new AccessDeniedException("Nomination is outside the permitted data scope");}
    private void createAccess(String employee,Long businessUnit,String actor,PermissionDataScope scope,String token){if(employee.equalsIgnoreCase(actor)||scope==PermissionDataScope.AGENCY_WIDE)return;if(scope!=PermissionDataScope.ASSIGNED_RECORDS)throw new AccessDeniedException("Own Records permission can nominate only the signed-in employee");HumanResourceAssessmentSubject supervisor=participants.getByEmployeeNo(actor,token);var membership=admin.membership(supervisor.employeeId(),token);if(!Objects.equals(membership.businessUnitId(),businessUnit)||(!membership.head()&&!membership.coApprover()))throw new AccessDeniedException("Supervisor may nominate only employees in their assigned Business Unit");}
    private void mutableEnrollment(String agency,String offering){if(orders.findByAgencyIdAndOfferingId(agency,offering).isPresent())throw new IllegalStateException("Enrollment is frozen by the approved Training Order source");}
    private boolean enrollmentVisible(String agency,LdEnrollment e,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||e.getEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&visible(agency,nomination(agency,e.getNominationId()),actor,scope);}
    private void enrollmentAccess(String agency,LdEnrollment e,String actor,PermissionDataScope scope){if(!enrollmentVisible(agency,e,actor,scope))throw new AccessDeniedException("Enrollment is outside the permitted data scope");}
    private void own(LdEnrollment e,String actor){if(!e.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the invited employee may make this enrollment decision");}
    private LdNomination nomination(String a,String id){return nominations.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D nomination not found"));}
    private LdEnrollment enrollment(String a,String id){return enrollments.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D enrollment not found"));}
    private LdOffering offering(String a,String id){return offerings.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D offering not found"));}
    private LdNominationRoute activeRoute(String a,String nomination){return routes.findFirstByAgencyIdAndNominationIdOrderByRouteRevisionDesc(a,nomination).filter(r->r.getStatus()==LdNominationRoute.Status.ACTIVE).orElseThrow(()->new IllegalStateException("Active nomination approval route not found"));}
    private NominationResponse response(String a,LdNomination n){List<RouteStepResponse> route=routes.findFirstByAgencyIdAndNominationIdOrderByRouteRevisionDesc(a,n.getId()).map(r->steps.findByAgencyIdAndRouteIdOrderByLevelAsc(a,r.getId()).stream().map(s->new RouteStepResponse(s.getLevel(),s.getAction().name(),s.getEmployeeNo(),s.getEmployeeName(),s.getStatus().name(),s.getDecidedBy(),s.getDecidedAt(),s.getDecisionReason())).toList()).orElse(List.of());return new NominationResponse(n.getId(),n.getVersion(),n.getOfferingId(),n.getOfferingVersion(),n.getOfferingTitle(),n.getScheduleStart(),n.getScheduleEnd(),n.getSourceType().name(),n.getSourceId(),n.getJustification(),n.getEmployeeId(),n.getEmployeeNo(),n.getEmployeeName(),n.getAppointmentId(),n.getBusinessUnitId(),n.getBusinessUnitName(),n.getEstimatedCost(),n.getInitiatorType().name(),n.getInitiatedBy(),n.getStatus().name(),n.getContentRevision(),n.getSubmittedBy(),n.getSubmittedAt(),n.getApprovedBy(),n.getApprovedAt(),n.getReturnReason(),route);}
    private EnrollmentResponse enrollmentResponse(LdEnrollment e){return new EnrollmentResponse(e.getId(),e.getVersion(),e.getNominationId(),e.getOfferingId(),e.getOfferingVersion(),e.getEmployeeId(),e.getEmployeeNo(),e.getEmployeeName(),e.getAppointmentId(),e.getStatus().name(),e.getConfirmedAt(),e.getCancelledAt(),e.getStatusReason(),e.getReplacesEnrollmentId(),e.getReplacedByEnrollmentId());}
    private TrainingOrderResponse orderResponse(String a,LdTrainingOrderSource o){return new TrainingOrderResponse(o.getId(),o.getVersion(),o.getOfferingId(),o.getOfferingVersion(),o.getOrderNumber(),o.getSubject(),o.getAttendanceDirective(),o.getDressCode(),o.getNotes(),o.getApprovedBy(),o.getApprovedAt(),o.getSnapshotFingerprint(),orderParticipants.findByAgencyIdAndTrainingOrderIdOrderByDisplayOrderAsc(a,o.getId()).stream().map(p->new TrainingOrderParticipantResponse(p.getEnrollmentId(),p.getEnrollmentVersion(),p.getEmployeeId(),p.getEmployeeNo(),p.getEmployeeName(),p.getAppointmentId(),p.getEnrollmentStatus(),p.getDisplayOrder())).toList());}
    private NominationResponse changed(String a,LdNomination n,String action,NominationResponse before,String reason,String c){NominationResponse out=response(a,n);record(a,action,"LD_NOMINATION",n.getId(),n.getContentRevision(),n.getVersion(),before,out,reason,c);return out;}
    private EnrollmentResponse enrollmentChanged(String a,LdEnrollment e,String action,EnrollmentResponse before,String reason,String c){EnrollmentResponse out=enrollmentResponse(e);record(a,action,"LD_ENROLLMENT",e.getId(),null,e.getVersion(),before,out,reason,c);return out;}
    private void record(String a,String action,String type,String id,Integer business,long version,Object before,Object after,String reason,String c){audit.record(a,action,type,id,business,version,before,after,reason,c);}
    private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
    private static String requiredReason(String value){if(value==null||value.isBlank())throw new IllegalArgumentException("reason is required");return value.trim();}
    private static String offeringFingerprint(LdOffering o){return hash(o.getId()+"|"+o.getVersion()+"|"+o.getOfferingVersion()+"|"+o.getTitle()+"|"+o.getStatus());}
    private String enrollmentFingerprint(LdEnrollment e){return hash(e.getId()+"|"+e.getVersion()+"|"+e.getEmployeeFingerprint()+"|"+e.getStatus());}
    private static String hash(Object value){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(String.valueOf(value).getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(bytes);}catch(Exception e){throw new IllegalStateException("Fingerprint could not be generated",e);}}
    private record Source(String id,Long version,String fingerprint){}
}
